export enum ROLES {
  ADMIN = 'ADMIN',
  USER = 'USER',
}

type RoleTypes = keyof typeof ROLES;

import { useState, useEffect } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/form/input';
import { Select } from '@/components/ui/select';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';

import { ROLES } from '@/lib/authorization';

import { useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';

type UserRoleFilter = '' | 'ADMIN' | 'USER';

const roleOptions = [
  { label: 'All', value: '' },
  { label: 'Admin', value: 'ADMIN' },
  { label: 'User', value: 'USER' },
];

const exportUsersCsv = (users: { firstName: string; lastName: string; email: string; role: string; createdAt: number }[]) => {
  const header = 'Name,Email,Role,Joined\n';
  const rows = users
    .map((u) => {
      const name = `"${u.firstName} ${u.lastName}"`;
      const email = `"${u.email}"`;
      const role = u.role;
      const joined = formatDate(u.createdAt);
      return `${name},${email},${role},${joined}`;
    })
    .join('\n');
  const csv = header + rows;
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'users.csv';
  link.click();
  URL.revokeObjectURL(url);
};

export const UsersList = () => {
  const [roleFilter, setRoleFilter] = useState<UserRoleFilter>('');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    setSearchQuery((prev) => prev.trim());
  }, [searchQuery]);

  const usersQuery = useUsers({
    params: {
      role: roleFilter || undefined,
      search: searchQuery || undefined,
    },
  });

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <div>
      <div className="mb-4 flex items-center gap-4">
        <Select
          options={roleOptions}
          value={roleFilter}
          onChange={(value) => setRoleFilter(value as UserRoleFilter)}
        />
        <Input
          placeholder="Search by name or email"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-64"
        />
        <Button
          variant="outline"
          onClick={() => exportUsersCsv(users)}
        >
          Export CSV
        </Button>
      </div>
      <Table
        data={users}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
    </div>
  );
};

